## 2. TCP Connection Manager

```csharp
// TcpConnectionManager.cs
public class TcpConnectionManager : IDisposable, IClientConnectionManager
{
    private readonly TcpListener _listener;
    private readonly ILogger<TcpConnectionManager> _logger;
    private readonly IClientConnectionFactory _connectionFactory;
    private readonly IClientConnectionLifetimeManager _lifetimeManager;
    private readonly IHeartbeatManager _heartbeatManager;
    private readonly IClientConnectionRegistry _connectionRegistry;
    private readonly CancellationTokenSource _cts = new();
    private Task _acceptTask;

    public TcpConnectionManager(
        int port,
        ILogger<TcpConnectionManager> logger,
        IClientConnectionFactory connectionFactory,
        IClientConnectionLifetimeManager lifetimeManager,
        IHeartbeatManager heartbeatManager,
        IClientConnectionRegistry connectionRegistry)
    {
        _listener = new TcpListener(IPAddress.Any, port);
        _logger = logger;
        _connectionFactory = connectionFactory;
        _lifetimeManager = lifetimeManager;
        _heartbeatManager = heartbeatManager;
        _connectionRegistry = connectionRegistry;
    }

    public async Task StartAsync(CancellationToken stoppingToken)
    {
        _listener.Start();
        _acceptTask = Task.Run(() => AcceptClientsAsync(stoppingToken));
    }

    private async Task AcceptClientsAsync(CancellationToken stoppingToken)
    {
        try
        {
            while (!_cts.IsCancellationRequested)
            {
                var client = await _listener.AcceptTcpClientAsync(stoppingToken);
                _logger.LogInformation("New client connected from {ClientAddress}", client.Client.RemoteEndPoint);

                var connection = _connectionFactory.Create(client, _heartbeatManager);
                _connectionRegistry.Register(connection);

                _ = HandleClientAsync(connection, stoppingToken);
            }
        }
        catch (OperationCanceledException)
        {
            _logger.LogInformation("TcpConnectionManager stopped accepting clients");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error accepting client connection");
        }
    }

    private async Task HandleClientAsync(IClientConnection connection, CancellationToken stoppingToken)
    {
        try
        {
            await connection.HandshakeAsync(stoppingToken);
            _logger.LogInformation("Client {ClientId} completed handshake", connection.ClientId);

            // Start heartbeat monitoring
            _heartbeatManager.StartMonitoring(connection);

            // Process messages
            await connection.ProcessMessagesAsync(stoppingToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error handling client {ClientId}", connection.ClientId);
        }
        finally
        {
            _connectionRegistry.Unregister(connection.ClientId);
            await connection.DisposeAsync();
        }
    }

    public void Stop()
    {
        _cts.Cancel();
        _listener.Stop();
        _acceptTask?.Wait();
    }

    public void Dispose()
    {
        _cts.Dispose();
        _listener.Dispose();
    }
}

