public interface IClientConnection : IAsyncDisposable
{
    Guid ClientId { get; }
    Task HandshakeAsync(CancellationToken cancellationToken);
    Task ProcessMessagesAsync(CancellationToken cancellationToken);
    Task SendAsync(byte[] message);
    Task SendAsync(string message);
