public class ClientConnection : IClientConnection
{
    private readonly TcpClient _tcpClient;
    private readonly NetworkStream _stream;
    private readonly IHeartbeatManager _heartbeatManager;
    private readonly ILogger<ClientConnection> _logger;
    private readonly IMessageSerializer _serializer;

    public Guid ClientId { get; }

    public ClientConnection(
        TcpClient tcpClient,
        IHeartbeatManager heartbeatManager,
        ILogger<ClientConnection> logger,
        IMessageSerializer serializer)
    {
        _tcpClient = tcpClient ?? throw new ArgumentNullException(nameof(tcpClient));
        _stream = tcpClient.GetStream();
        _heartbeatManager = heartbeatManager ?? throw new ArgumentNullException(nameof(heartbeatManager));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _serializer = serializer ?? throw new ArgumentNullException(nameof(serializer));
        ClientId = Guid.NewGuid();
    }

    public async Task HandshakeAsync(CancellationToken cancellationToken)
    {
        // Implement handshake protocol (version, capabilities, etc.)
        var handshakeMessage = await _stream.ReadAsync(new byte[1024], cancellationToken);
        var handshakeData = _serializer.Deserialize(handshakeMessage);

        // Validate handshake and establish connection parameters
        // ...
    }

    public async Task ProcessMessagesAsync(CancellationToken cancellationToken)
    {
        var buffer = new byte[4096];
        while (!_tcpClient.Connected && !cancellationToken.IsCancellationRequested)
        {
            try
            {
                var bytesRead = await _stream.ReadAsync(buffer, cancellationToken);
                if (bytesRead == 0) break;

                var message = _serializer.Deserialize(buffer[..bytesRead]);
                // Process message (route to appropriate handler)
                // ...
            }
            catch (IOException)
            {
                // Client disconnected
                break;
            }
        }
    }

    public async Task SendAsync(byte[] message)
    {
        await _stream.WriteAsync(message);
    }

    public async Task SendAsync(string message)
    {
        var bytes = _serializer.Serialize(message);
        await SendAsync(bytes);
    }

    public async ValueTask DisposeAsync()
    {
        await _stream.DisposeAsync();
        await _tcpClient.DisposeAsync();
    }
}

// HeartbeatManager.cs
public class HeartbeatManager : IHeartbeatManager
{
    private readonly ILogger<HeartbeatManager> _logger;
    private readonly IClientConnectionRegistry _connectionRegistry;
    private readonly TimeSpan _heartbeatInterval;
    private readonly TimeSpan _timeoutDuration;
    private readonly CancellationTokenSource _cts = new();
    private Task _heartbeatTask;

    public HeartbeatManager(
        ILogger<HeartbeatManager> logger,
        IClientConnectionRegistry connectionRegistry,
        TimeSpan heartbeatInterval = default,
        TimeSpan timeoutDuration = default)
    {
        _logger = logger;
        _connectionRegistry = connectionRegistry;
        _heartbeatInterval = heartbeatInterval ?? TimeSpan.FromSeconds(30);
        _timeoutDuration = timeoutDuration ?? TimeSpan.FromMinutes(5);
    }

    public void StartMonitoring(IClientConnection connection)
    {
        _ = SendHeartbeatAsync(connection);
    }

    private async Task SendHeartbeatAsync(IClientConnection connection)
    {
        try
        {
            while (!_cts.IsCancellationRequested)
            {
                await Task.Delay(_heartbeatInterval, _cts.Token);
                await connection.SendAsync("PING");
            }
        }
        catch (OperationCanceledException)
        {
            _logger.LogDebug("Heartbeat monitoring stopped for client {ClientId}", connection.ClientId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error sending heartbeat to client {ClientId}", connection.ClientId);
        }
    }

    public void Stop()
    {
        _cts.Cancel();
    }

    public void Dispose()
    {
        _cts.Dispose();
    }
}
