## 3. Room Management Subsystem

```csharp
// RoomManager.cs
public class RoomManager : IRoomManager
{
    private readonly ILogger<RoomManager> _logger;
    private readonly IClientConnectionRegistry _connectionRegistry;
    private readonly IMessageBroker _messageBroker;
    private readonly Dictionary<string, Room> _rooms = new();
    private readonly object _roomsLock = new();

    public RoomManager(
        ILogger<RoomManager> logger,
        IClientConnectionRegistry connectionRegistry,
        IMessageBroker messageBroker)
    {
        _logger = logger;
        _connectionRegistry = connectionRegistry;
        _messageBroker = messageBroker;
    }

    public async Task<string> CreateRoomAsync(string roomName, string creatorId, RoomPermissions permissions)
    {
        var roomId = Guid.NewGuid().ToString();
        var room = new Room(roomId, roomName, creatorId, permissions);

        lock (_roomsLock)
        {
            _rooms[roomId] = room;
        }

        _logger.LogInformation("Room {RoomId} created by {CreatorId}", roomId, creatorId);
        return roomId;
    }

    public async Task JoinRoomAsync(Guid clientId, string roomId)
    {
        Room room;
        lock (_roomsLock)
        {
            if (!_rooms.TryGetValue(roomId, out room))
                throw new RoomNotFoundException(roomId);
        }

        if (!room.CanJoin(clientId))
            throw new UnauthorizedAccessException($"Client {clientId} is not authorized to join room {roomId}");

        room.AddMember(clientId);
        _logger.LogInformation("Client {ClientId} joined room {RoomId}", clientId, roomId);

        // Notify other members
        await _messageBroker.BroadcastToRoomAsync(roomId, $"User {clientId} joined the room");
    }

    public async Task LeaveRoomAsync(Guid clientId, string roomId)
    {
        Room room;
        lock (_roomsLock)
        {
            if (!_rooms.TryGetValue(roomId, out room))
                throw new RoomNotFoundException(roomId);
        }

        room.RemoveMember(clientId);
        _logger.LogInformation("Client {ClientId} left room {RoomId}", clientId, roomId);

        // Notify other members
        await _messageBroker.BroadcastToRoomAsync(roomId, $"User {clientId} left the room");
    }

    public async Task SendMessageAsync(Guid clientId, string roomId, string message)
    {
        Room room;
        lock (_roomsLock)
        {
            if (!_rooms.TryGetValue(roomId, out room))
                throw new RoomNotFoundException(roomId);
        }

        if (!room.CanSendMessage(clientId))
            throw new UnauthorizedAccessException($"Client {clientId} is not authorized to send messages in room {roomId}");

        var messageData = new ChatMessage
        {
            Id = Guid.NewGuid(),
            SenderId = clientId,
            RoomId = roomId,
            Content = message,
            Timestamp = DateTime.UtcNow
        };

        // Broadcast to room
        await _messageBroker.BroadcastToRoomAsync(roomId, messageData);

        // Persist message
        await _messageBroker.PersistMessageAsync(messageData);
    }

    public async Task<IEnumerable<Room>> GetUserRoomsAsync(Guid clientId)
    {
        lock (_roomsLock)
        {
            return _rooms.Values
                .Where(room => room.Members.Contains(clientId))
                .ToList();
        }
    }

    public async Task<IEnumerable<Room>> GetAllRoomsAsync()
    {
        lock (_roomsLock)
        {
            return _rooms.Values.ToList();
        }
    }
}

