## 4. Message Persistence Engine

```csharp
// MessagePersistenceEngine.cs
public class MessagePersistenceEngine : IMessagePersistenceEngine
{
    private readonly ILogger<MessagePersistenceEngine> _logger;
    private readonly IMessageBroker _messageBroker;
    private readonly IChatDatabaseContext _dbContext;
    private readonly IBackgroundTaskQueue _taskQueue;
    private readonly TimeSpan _batchInterval;
    private readonly int _batchSize;

    public MessagePersistenceEngine(
        ILogger<MessagePersistenceEngine> logger,
        IMessageBroker messageBroker,
        IChatDatabaseContext dbContext,
        IBackgroundTaskQueue taskQueue,
        TimeSpan batchInterval = default,
        int batchSize = 100)
    {
        _logger = logger;
        _messageBroker = messageBroker;
        _dbContext = dbContext;
        _taskQueue = taskQueue;
        _batchInterval = batchInterval ?? TimeSpan.FromSeconds(5);
        _batchSize = batchSize;

        _taskQueue.QueueBackgroundWorkItem(async () => await ProcessMessagesAsync());
    }

    public async Task PersistMessageAsync(ChatMessage message)
    {
        // Queue the message for persistence
        await _taskQueue.QueueBackgroundWorkItem(async () =>
        {
            try
            {
                await _dbContext.ChatMessages.AddAsync(message);
                await _dbContext.SaveChangesAsync();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error persisting message {MessageId}", message.Id);
            }
        });
    }

    private async Task ProcessMessagesAsync()
    {
        var batch = new List<ChatMessage>();
        var lastProcessed = DateTime.UtcNow;

        while (true)
        {
            try
            {
                // Wait for new messages or batch interval
                var waitTime = _batchInterval - (DateTime.UtcNow - lastProcessed);
                if (waitTime > TimeSpan.Zero)
                {
                    await Task.Delay(waitTime);
                }

                // Process any pending messages
                if (_messageBroker.HasPendingMessages)
                {
                    var messages = await _messageBroker.GetPendingMessagesAsync();
                    batch.AddRange(messages);

                    if (batch.Count >= _batchSize)
                    {
                        await ProcessBatchAsync(batch);
                        batch.Clear();
                    }
                }

                lastProcessed = DateTime.UtcNow;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error in message persistence batch processing");
            }
        }
    }

    private async Task ProcessBatchAsync(IEnumerable<ChatMessage> messages)
    {
        try
        {
            await _dbContext.ChatMessages.AddRangeAsync(messages);
            await _dbContext.SaveChangesAsync();
            _logger.LogInformation("Persisted {Count} messages to database", messages.Count());
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing batch of {Count} messages", messages.Count());
            // Implement retry logic here
        }
    }
}

