## 5. Message Broker (Integration Point)

```csharp
// MessageBroker.cs
public class MessageBroker : IMessageBroker
{
    private readonly ILogger<MessageBroker> _logger;
    private readonly IClientConnectionRegistry _connectionRegistry;
    private readonly IMessagePersistenceEngine _persistenceEngine;
    private readonly ConcurrentDictionary<string, HashSet<Guid>> _roomSubscriptions = new();
    private readonly ConcurrentQueue<ChatMessage> _pendingMessages = new();

    public MessageBroker(
        ILogger<MessageBroker> logger,
        IClientConnectionRegistry connectionRegistry,
        IMessagePersistenceEngine persistenceEngine)
    {
        _logger = logger;
        _connectionRegistry = connectionRegistry;
        _persistenceEngine = persistenceEngine;
    }

    public bool HasPendingMessages => _pendingMessages.Count > 0;

    public async Task<ChatMessage[]> GetPendingMessagesAsync()
    {
        var messages = new List<ChatMessage>();
        while (_pendingMessages.TryDequeue(out var message))
        {
            messages.Add(message);
        }
        return messages.ToArray();
    }

    public async Task BroadcastToRoomAsync(string roomId, ChatMessage message)
    {
        // Add to persistence queue
        _pendingMessages.Enqueue(message);

        // Broadcast to all subscribers
        var subscribers = _roomSubscriptions.GetOrAdd(roomId, _ => new HashSet<Guid>());
        var activeSubscribers = subscribers.Where(id => _connectionRegistry.IsConnected(id)).ToList();

        foreach (var clientId in activeSubscribers)
        {
            try
            {
                var connection = _connectionRegistry.GetConnection(clientId);
                if (connection != null)
                {
                    await connection.SendAsync(message);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error broadcasting message to client {ClientId}", clientId);
            }
        }
    }

    public async Task SubscribeToRoomAsync(Guid clientId, string roomId)
    {
        _roomSubscriptions.AddOrUpdate(roomId, new HashSet<Guid> { clientId },
            (key, existing) =>
            {
                existing.Add(clientId);
                return existing;
            });
    }

    public async Task UnsubscribeFromRoomAsync(Guid clientId, string roomId)
    {
        if (_roomSubscriptions.TryGetValue(roomId, out var subscribers))
        {
            subscribers.Remove(clientId);
            if (subscribers.Count == 0)
            {
                _roomSubscriptions.TryRemove(roomId, out _);
            }
        }
    }

    public async Task PersistMessageAsync(ChatMessage message)
    {
        await _persistenceEngine.PersistMessageAsync(message);
    }
}
