// Program.cs
public static class Program
{
    public static async Task Main(string[] args)
    {
        var builder = Host.CreateApplicationBuilder(args);

        // Configure services
        builder.Services.AddHostedService<ChatServer>();
        builder.Services.AddSingleton<IChatServerFactory, ChatServerFactory>();

        // TCP Connection Manager
        builder.Services.AddSingleton<IClientConnectionManager, TcpConnectionManager>();
        builder.Services.AddSingleton<IClientConnectionFactory, ClientConnectionFactory>();
        builder.Services.AddSingleton<IClientConnectionRegistry, ClientConnectionRegistry>();
        builder.Services.AddSingleton<IHeartbeatManager, HeartbeatManager>();
        builder.Services.AddSingleton<IMessageSerializer, MessageSerializer>();

        // Room Management
        builder.Services.AddSingleton<IRoomManager, RoomManager>();
        builder.Services.AddSingleton<IMessageBroker, MessageBroker>();

        // Message Persistence
        builder.Services.AddDbContext<ChatDatabaseContext>(options =>
            options.UseSqlServer(builder.Configuration.GetConnectionString("ChatDatabase")));
        builder.Services.AddSingleton<IMessagePersistenceEngine, MessagePersistenceEngine>();
        builder.Services.AddSingleton<IBackgroundTaskQueue, BackgroundTaskQueue>();

        // Logging
        builder.Logging.AddConsole();
        builder.Logging.AddDebug();

        var app = builder.Build();

        await app.RunAsync();
    }
}

